/* NexRaven site intro: a till scans a barcode, the bars hatch into a flock of 3D birds,
   the flock lands as the raven (red birds form the N) and NEXRAVEN decodes.
   Plays once per visitor; Skip / Esc end it; ?intro=1 forces it; reduced motion never shows it.
   The decision to show it is made inline in index.html so there is no flash. */
(function () {
  "use strict";
  var root = document.getElementById("intro");
  if (!root || root.hidden) return;

  var cv = root.querySelector("canvas"), ctx = cv.getContext("2d");
  var word = root.querySelector(".intro-word"), sub = root.querySelector(".intro-sub"), tag = root.querySelector(".intro-tag");
  var titleBox = root.querySelector(".intro-title"), skip = root.querySelector(".intro-skip");
  var isAR = document.documentElement.lang === "ar";
  tag.textContent = isAR ? "ميزان · نظام كاشير ومخزون ومحاسبة" : "Mizan · POS, stock and accounting";
  skip.textContent = isAR ? "تخطّي" : "Skip";

  var DPR = Math.min(window.devicePixelRatio || 1, 2), W = 0, H = 0;
  var P = [], links = [], bars = [], t0 = 0, last = 0, done = false;
  var box = { x: 0, y: 0, w: 0, h: 0 }, bar = { x: 0, y: 0, w: 0, h: 0 }, mouse = { x: -9999, y: -9999 };
  var T = { scan: 1.1, burst: 2.0, flock: 3.8, land: 5.6, hold: 8.6 };
  function rnd(a, b) { return a + Math.random() * (b - a); }

  function finish() {
    if (done) return;
    done = true;
    try { localStorage.setItem("nr-intro-seen", "1"); } catch (e) {}
    root.classList.add("intro-out");
    document.documentElement.classList.remove("intro-on");
    setTimeout(function () { root.remove(); }, 700);
  }
  skip.addEventListener("click", finish);
  document.addEventListener("keydown", function (e) { if (e.key === "Escape") finish(); });

  function layout() {
    W = window.innerWidth; H = window.innerHeight;
    cv.width = W * DPR; cv.height = H * DPR; ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    box.w = Math.min(540, W * 0.8, (H - 260) * (520 / 402)); box.h = box.w * (402 / 520);
    box.x = (W - box.w) / 2; box.y = Math.max(24, (H - 260 - box.h) / 2 + 10);
    bar.w = Math.min(360, W * 0.7); bar.h = bar.w * 0.42; bar.x = (W - bar.w) / 2; bar.y = box.y + box.h / 2 - bar.h / 2;
    titleBox.style.top = (box.y + box.h + 16) + "px";
  }

  function build(img) {
    var oc = document.createElement("canvas"); oc.width = img.width; oc.height = img.height;
    var o = oc.getContext("2d"); o.drawImage(img, 0, 0);
    var d = o.getImageData(0, 0, img.width, img.height).data, pts = [];
    for (var y = 0; y < img.height; y += 2) for (var x = 0; x < img.width; x += 2) {
      var i = (y * img.width + x) * 4;
      if (d[i + 3] < 140) continue;
      pts.push({ u: x / img.width, v: y / img.height, red: d[i] > 150 && d[i + 1] < 110 && d[i + 2] < 110 });
    }
    var cap = W < 600 ? 800 : 1600;
    while (pts.length > cap) pts.splice(Math.floor(Math.random() * pts.length), 1);

    var u = 0;
    while (u < 1) {
      var bw = [0.008, 0.014, 0.022, 0.034][Math.floor(Math.random() * 4)];
      if (u + bw > 1) break;
      bars.push({ u: u, w: bw });
      u += bw + [0.014, 0.02, 0.03][Math.floor(Math.random() * 3)];
    }
    P = pts.map(function (m, i) {
      var b = bars[i % bars.length];
      return { red: m.red, mu: m.u, s: rnd(1.1, 2), a: rnd(0.6, 1), seed: Math.random() * 1000, z: rnd(-1, 1),
        rx: box.x + m.u * box.w, ry: box.y + m.v * box.h,
        bx: bar.x + (b.u + b.w * 0.1 + Math.random() * b.w * 0.8) * bar.w, by: bar.y + Math.random() * bar.h, vx: 0, vy: 0 };
    });
    P.forEach(function (p) { p.x = p.bx + rnd(-30, 30); p.y = p.by + rnd(-160, 160); });
    P.sort(function (a, b) { return a.z - b.z; });
    var smp = P.filter(function (_, i) { return i % 5 === 0; });
    for (var a = 0; a < smp.length && links.length < 700; a++) for (var c = a + 1; c < smp.length; c++) {
      var dx = smp[a].rx - smp[c].rx, dy = smp[a].ry - smp[c].ry, dd = dx * dx + dy * dy;
      if (dd < 32 * 32 && dd > 81) links.push([smp[a], smp[c]]);
    }
  }

  var GLYPHS = "█▓▒░<>/|=+*#%01";
  function drawWord(prog) {
    var target = "NEXRAVEN", html = "";
    for (var i = 0; i < 8; i++) {
      var ok = prog * 10 > i + 1.2, ch = ok ? target[i] : GLYPHS[Math.floor(Math.random() * GLYPHS.length)];
      html += '<span class="' + (i < 3 ? "r" : "") + '" style="opacity:' + (ok ? 1 : 0.5) + '">' + ch.replace("<", "&lt;").replace(">", "&gt;") + "</span>";
    }
    word.innerHTML = html;
    var s = "FOR RETAIL SOLUTIONS";
    sub.textContent = s.slice(0, Math.floor(Math.max(0, prog - 0.45) / 0.55 * s.length));
  }

  // 3D birds, side-on: far wing, body, near wing; shades bucketed into a few fills
  var SHADES = [0.38, 0.55, 0.72, 0.88, 1];
  function shadeIdx(v) { for (var i = 0; i < SHADES.length; i++) if (v <= SHADES[i]) return i; return SHADES.length - 1; }
  function angDiff(a, b) { var d = a - b; while (d > Math.PI) d -= 2 * Math.PI; while (d < -Math.PI) d += 2 * Math.PI; return d; }
  function drawBirds(t, redness) {
    var white = [], red = [], i, p;
    for (i = 0; i < SHADES.length; i++) { white.push(new Path2D()); red.push(new Path2D()); }
    for (i = 0; i < P.length; i++) {
      p = P[i];
      var dx = p.rx - p.x, dy = p.ry - p.y, near = dx * dx + dy * dy < 22 * 22 && t > T.flock;
      var want = near ? Math.sin(t * 1.3 + p.seed) * 0.18 : Math.atan2(p.vy, p.vx);
      p.h = p.h == null ? want : p.h + angDiff(want, p.h) * (near ? 0.08 : 0.25);
      var flip = Math.cos(p.h) < 0 ? -1 : 1, ang = flip < 0 ? p.h - Math.PI : p.h;
      var s = (near ? 4 : 5) * (1 + p.z * 0.4) * (W < 600 ? 0.8 : 1);
      var flap = Math.cos(t * (near ? 7 : 17) + p.seed), c = Math.cos(ang), sn = Math.sin(ang);
      var set = (p.red && redness > 0.5) ? red : white, fade = 0.55 + 0.45 * (p.z + 1) / 2;
      var px = p.x, py = p.y;
      var pt = function (lx, ly) { lx *= flip; return [px + lx * c - ly * sn, py + lx * sn + ly * c]; };
      var tri = function (path, A, B, C) { path.moveTo(A[0], A[1]); path.lineTo(B[0], B[1]); path.lineTo(C[0], C[1]); path.closePath(); };
      tri(set[shadeIdx(0.38 * fade)], pt(0.25 * s, -0.05 * s), pt(-0.3 * s, -0.05 * s), pt(0.05 * s, -s * (0.25 + 0.85 * flap) * 0.8));
      tri(set[shadeIdx(0.72 * fade)], pt(0.95 * s, 0), pt(-0.75 * s, 0.17 * s), pt(-0.75 * s, -0.17 * s));
      tri(set[shadeIdx((0.6 + 0.4 * flap) * fade)], pt(0.3 * s, 0.02 * s), pt(-0.35 * s, 0.02 * s), pt(-0.1 * s, -s * (0.3 + 1.05 * flap)));
    }
    ctx.globalCompositeOperation = "source-over";
    for (i = 0; i < SHADES.length; i++) {
      var k = SHADES[i];
      ctx.fillStyle = "rgba(" + Math.round(225 * k) + "," + Math.round(232 * k) + "," + Math.round(236 * k) + ",.95)"; ctx.fill(white[i]);
      ctx.fillStyle = "rgba(255," + Math.round(40 * k) + "," + Math.round(40 * k) + "," + (0.55 + 0.45 * k) + ")"; ctx.fill(red[i]);
    }
  }

  function step(now) {
    if (done) return;
    requestAnimationFrame(step);
    // fixed 60 Hz physics with catch-up sub-steps: on a slow phone the story keeps its timing
    var dt = Math.min(0.25, (now - (last || now)) / 1000); last = now;
    var t = (now - t0) / 1000, subSteps = Math.max(1, Math.min(15, Math.round(dt * 60)));
    if (t > T.hold) { finish(); return; }

    ctx.globalCompositeOperation = "source-over";
    ctx.fillStyle = t > T.burst && t < T.land + 0.6 ? "rgba(34,45,50,.45)" : "rgba(34,45,50,.7)";
    ctx.fillRect(0, 0, W, H);

    var laserX = bar.x - 20 + (bar.w + 40) * Math.min(1, Math.max(0, (t - 0.2) / (T.scan - 0.2)));
    var ft = t - T.burst, ax = W / 2 + Math.sin(ft * 1.3) * W * 0.3, ay = H * 0.42 + Math.sin(ft * 2.1 + 1) * H * 0.2;
    var i, p, damp;
    for (var sub = 0; sub < subSteps; sub++)
    for (i = 0; i < P.length; i++) {
      p = P[i];
      if (t < T.burst) {
        damp = 0.72; p.vx += (p.bx - p.x) * 0.12; p.vy += (p.by - p.y) * 0.12;
      } else {
        if (!p.go) { p.go = true; var an = rnd(0, Math.PI * 2), sp = rnd(4, 13); p.vx += Math.cos(an) * sp; p.vy += Math.sin(an) * sp - 3; }
        var on = t - T.flock - (p.mu * 0.9 + (p.seed % 1) * 0.25);
        if (on < 0) {
          p.vx += (ax - p.x) * 0.0016 + Math.sin(p.y * 0.008 + ft * 1.7 + p.seed) * 0.9;
          p.vy += (ay - p.y) * 0.0016 + Math.cos(p.x * 0.008 - ft * 1.3 + p.seed) * 0.9;
          damp = 0.94;
        } else {
          var k = Math.min(0.09, 0.012 + on * 0.05), tx = p.rx, ty = p.ry;
          if (t > T.land) { tx += Math.sin(t * 2 + p.seed) * 0.6; ty += Math.cos(t * 2.3 + p.seed) * 0.6; }
          p.vx += (tx - p.x) * k; p.vy += (ty - p.y) * k; damp = 0.8;
          var mdx = p.x - mouse.x, mdy = p.y - mouse.y, md = Math.hypot(mdx, mdy);
          if (md < 100 && t > T.land) { var f = (1 - md / 100) * 6; p.vx += mdx / (md + 0.01) * f; p.vy += mdy / (md + 0.01) * f; }
        }
      }
      p.vx *= damp; p.vy *= damp; p.x += p.vx; p.y += p.vy;
    }

    var redness = Math.min(1, Math.max(0, (t - T.flock - 0.5) / 1.1));
    if (t < T.burst) {
      ctx.globalCompositeOperation = "lighter";
      for (i = 0; i < P.length; i++) {
        p = P[i];
        ctx.fillStyle = p.x < laserX ? "rgba(255,90,90," + p.a + ")" : "rgba(225,232,236," + (0.75 * p.a) + ")";
        ctx.fillRect(p.x, p.y, p.s, p.s);
      }
      if (t > 0.15 && t < T.scan + 0.2) {
        var g = ctx.createLinearGradient(laserX - 22, 0, laserX + 22, 0);
        g.addColorStop(0, "rgba(255,0,0,0)"); g.addColorStop(0.5, "rgba(255,30,30,.9)"); g.addColorStop(1, "rgba(255,0,0,0)");
        ctx.fillStyle = g; ctx.fillRect(laserX - 22, bar.y - 24, 44, bar.h + 48);
        ctx.fillStyle = "rgba(255,255,255,.9)"; ctx.fillRect(laserX - 1, bar.y - 24, 2, bar.h + 48);
      }
      if (t > T.scan && t < T.scan + 0.3) { ctx.globalCompositeOperation = "source-over"; ctx.fillStyle = "rgba(255,0,0," + (0.16 * (1 - (t - T.scan) / 0.3)) + ")"; ctx.fillRect(0, 0, W, H); }
    } else {
      drawBirds(t, redness);
    }

    if (t > T.land - 0.6) {
      ctx.globalCompositeOperation = "lighter";
      ctx.strokeStyle = "rgba(176,190,197," + Math.min(1, (t - T.land + 0.6) / 1.2) * 0.2 + ")"; ctx.lineWidth = 0.6; ctx.beginPath();
      for (i = 0; i < links.length; i++) { ctx.moveTo(links[i][0].x, links[i][0].y); ctx.lineTo(links[i][1].x, links[i][1].y); }
      ctx.stroke();
    }
    if (t > T.land - 0.3) drawWord(Math.min(1, (t - T.land + 0.3) / 1.5));
    if (t > T.land + 1.4) tag.classList.add("on");
  }

  window.addEventListener("pointermove", function (e) { mouse.x = e.clientX; mouse.y = e.clientY; });
  window.addEventListener("resize", function () { if (!done) layout(); });

  var img = new Image();
  img.onload = function () {
    layout(); build(img); t0 = performance.now();
    requestAnimationFrame(step);
  };
  img.onerror = finish;               // never trap visitors behind a broken intro
  // embedded so the intro also works when the page is opened straight from disk (no canvas taint)
  img.src = "data:image/png;base64,";
  setTimeout(function () { if (!t0) finish(); }, 4000); // if the image is slow, just show the site
})();
